import{z as B,x as i,o as E,c as d,q as n,j as s,D as e,d as o,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"序号缺口与丢包","description":"","frontmatter":{"title":"序号缺口与丢包","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sequence-gap.md","filePath":"quant/sequence-gap.md","lastUpdated":1791063341000}'),p={name:"quant/sequence-gap.md"};function A(c,a,h,u,_,C){const t=i("Mermaid");return E(),d("div",null,[a[2]||(a[2]=n('<h1 id="序号缺口与丢包" tabindex="-1">序号缺口与丢包 <a class="header-anchor" href="#序号缺口与丢包" aria-label="Permalink to &quot;序号缺口与丢包&quot;">​</a></h1><div class="epigraph"><p>时间戳告诉你事件贴了什么钟；序号告诉你事件有没有少一截。时钟对齐之后仍可能丢包，缺口会把队列、成交与撤单变成另一个市场。</p><footer>—— 据交易所 ITCH / 订单簿馈送对 sequence number 的公开规格；对照 Hasbrouck 对完整逐笔记录的要求</footer></div><p><a href="/quant/exchange-vs-broker-ts">交易所 vs 经纪商时钟</a>选定了撮合主键。本课的缺口是完整性：馈送与订单回报几乎都带单调序号。序号跳号、重复、乱序，表示丢包、重放或你读错了会话。L2/L3 重建若在缺口上继续，簿是错的，后续所有价差与队列研究都是错的。本课写检测、停机、重放与对账，不写如何利用丢失的行情去交易。后课公司行动引擎处理的是经济事件缺口，不是传输缺口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ITCH 一类增量馈送是「在序号 \\(n\\) 的簿上应用消息 \\(n+1\\)」。丢掉 \\(n+1\\)，本地簿与交易所真簿永久分叉，直到快照重置。症状可能像：负深度、交叉的 BBO、成交价远离你的买一。若只用价格过滤把这些当异常成交删掉，你在删真市场，因为缺口后的打印相对你的错簿看起来像错价。问题是把序号当成一等公民：任何增量行情会话都必须监测 <code>seq</code> 连续性，缺口时进入「簿不可用」，而不是继续提供假 BBO 给策略。</p><p>订单回报同样有序号。丢掉成交回报，库存会少一笔，做市会重复卖。丢掉撤单回报，会以为自己还在队列里。时钟再准，缺事件也比乱序更致命——乱序至少还能缓冲重排，缺事件必须重放。</p><p><span class="marginnote">直觉类比：增量行情像听人报数——「下一个是 47」。如果你听到 46 之后直接跳到 48，说明中间那句丢了；你不能假装 47 不存在继续记账，必须请他重说那一句（重放），否则你的账从那一刻起就和现场对不上了。</span></p><h3 id="乱序、重复与缺口是三种病" tabindex="-1">乱序、重复与缺口是三种病 <a class="header-anchor" href="#乱序、重复与缺口是三种病" aria-label="Permalink to &quot;乱序、重复与缺口是三种病&quot;">​</a></h3><p>乱序：后发先至，缓冲按序号重排即可，预算消耗的是延迟。重复：重传，应按序号去重，否则成交翻倍。缺口：中间的序号永远不来，必须向重放服务要 \\([n+1, n+k]\\) 或拉快照。把三者都叫「丢包」，处理会错。网络 UDP 行情尤其要把这三种分开。</p><p><span class="marginnote">A 股有的行情源不提供可用于重建簿的序号，只提供快照。此时不存在「增量缺口」，存在的是快照间隔内的不可观测。不要假装用快照差分当 L3。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会话状态机：<code>synced</code> / <code>gap</code> / <code>recovering</code> / <code>stale</code>。进入 <code>gap</code> 立即切断该场所的可交易报价（风控见闸门课），允许策略转到其他场所或停止做市。恢复：优先增量重放，失败则快照 + 追上增量，直到序号再次连续。恢复期间的本地 PnL 用「不可用」而不是用旧 BBO 估值——旧 BBO 在缺口后没有定义。</p>',12)),(E(),s(l,null,{default:e(()=>[r(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SY%5B%22synced%3A%20%E5%BA%8F%E5%8F%B7%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%7C%E5%8F%91%E7%8E%B0%E8%B7%B3%E5%8F%B7%7C%20GAP%5B%22gap%3A%20%E5%88%87%E6%96%AD%E8%AF%A5%E5%9C%BA%E6%89%80%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20GAP%20--%3E%20REC%5B%22recovering%3A%20%E5%A2%9E%E9%87%8F%E9%87%8D%E6%94%BE%22%5D%0A%20%20REC%20--%3E%7C%E9%87%8D%E6%94%BE%E5%A4%B1%E8%B4%A5%7C%20SNAP%5B%22%E6%8B%89%E5%BF%AB%E7%85%A7%E5%90%8E%E8%BF%BD%E5%A2%9E%E9%87%8F%22%5D%0A%20%20SNAP%20--%3E%20REC%0A%20%20REC%20--%3E%7C%E5%BA%8F%E5%8F%B7%E6%81%A2%E5%A4%8D%E8%BF%9E%E7%BB%AD%7C%20SY%0A%20%20SY%20--%3E%7C%E5%BF%83%E8%B7%B3%E8%B6%85%E6%97%B6%7C%20ST%5B%22stale%3A%20%E6%A0%87%E8%AE%B0%E4%B8%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20ST%20--%3E%7C%E5%BF%AB%E7%85%A7%E9%87%8D%E5%BB%BA%E5%AE%8C%E6%88%90%7C%20SY%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>对账：把交易所官方成交文件（带序号）与本地成交集合做差。只出现在官方的，是丢回报；只出现在本地的，是重复或错会话。与经纪商账单的差，回到上一课的时钟主键。统计应报缺口次数、缺口长度分布、恢复时长——这是系统可靠性，不是 alpha。</p><p><span class="marginnote">数字实例：一次 5 秒的缺口，在每 10 毫秒一条的行情里约丢 500 条消息；若簿重建在缺口后照跑，之后每一条 BBO、每一个队列位置都是虚构的。对高频做市，5 秒错簿足以让库存对冲全错——这就是「gap 即切断」比「事后修补」便宜的原因。</span></p><h3 id="研究样本里的缺口" tabindex="-1">研究样本里的缺口 <a class="header-anchor" href="#研究样本里的缺口" aria-label="Permalink to &quot;研究样本里的缺口&quot;">​</a></h3><p>历史数据库若在缺口处把簿「平滑」过去，回测会含有不存在的深度。正确做法是给时间段打 <code>data_quality</code> 标志，策略回测默认剔除或降权。高频体制对缺口敏感；低频日度 bar 若由错簿合成，开盘价也可能坏。质量标志必须沿用到因子研究，不能只给做市看。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>增量馈送把市场状态压缩成事件流。完整性是状态可恢复的前提。缺口的经济后果是：你以为的价差、深度、队列位置全部是另一个随机场。用它估实现价差或 lambda，估计的是你的 bug。Hasbrouck 要求逐笔记录完整，不是为了吹纳秒，是为了状态有定义。</p><p>重放本身消耗延迟预算。频繁缺口等于把高频策略的延迟分布加上长尾。工程上应把馈送冗余（主备序号独立）当成延迟预算的一部分，而不是当成「多买一路行情」。</p><p><span class="marginnote">加密 websocket 经常无可靠序号或重连后无缝隙快照。状态机更应保守：重连即 <code>stale</code> 直到完整快照。不要把股票 ITCH 的假设搬过去。</span></p>',8)),(E(),s(l,null,{default:e(()=>[r(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%A2%9E%E9%87%8F%E6%B6%88%E6%81%AF%20seq%3Dn%22%5D%20--%3E%20K%5B%22%E6%9C%9F%E6%9C%9B%20n%20%3D%20last%2B1%22%5D%0A%20%20K%20--%3E%7C%22%E6%98%AF%22%7C%20S%5B%22%E5%BA%94%E7%94%A8%E5%88%B0%E7%B0%BF%22%5D%0A%20%20K%20--%3E%7C%22%E4%B9%B1%E5%BA%8F%22%7C%20B%5B%22%E7%BC%93%E5%86%B2%E9%87%8D%E6%8E%92%22%5D%0A%20%20K%20--%3E%7C%22%E8%B7%B3%E5%8F%B7%22%7C%20G%5B%22gap%EF%BC%9A%E5%88%87%E6%96%AD%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20G%20--%3E%20R%5B%22%E9%87%8D%E6%94%BE%E6%88%96%E5%BF%AB%E7%85%A7%22%5D%0A%20%20R%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h3 id="快照重置之前禁止用旧簿估值" tabindex="-1">快照重置之前禁止用旧簿估值 <a class="header-anchor" href="#快照重置之前禁止用旧簿估值" aria-label="Permalink to &quot;快照重置之前禁止用旧簿估值&quot;">​</a></h3><p>缺口恢复期间若继续用上一口 BBO 做盘中 PnL，会把假深度写成真敞口。状态应是「该场所不可用」，估值改用备用源或标缺失。宁可少一个数字，不要一个错数字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不覆盖应用层业务拒绝（价格、权限），那是拒单监控。公司行为导致的合约代码变更，看起来像「品种消失」而不是 seq 跳号，下一课处理。跨所没有统一序号，不能用一个全局 seq 去对全国簿。</p><p><span class="marginnote">常见误区：初学者容易把「收到行情」当成「行情完整」。TCP 或自动重连的库会掩盖缺口，回测照样能跑出曲线——错的不是价格，是你重建的深度与队列。判断标准只有一条：序号是否连续、快照是否对上；没有这两样，再像样的簿都是想象。</span></p><p><span class="marginnote">研究库若在缺口处平滑深度，低频日 bar 也可能被污染。质量标志必须传到因子样本，不能只给做市看。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>序号连续性检验的是完整性；时钟检验的是对齐。两者都要。</li><li>缺口时簿不可用，必须切断报价并重放，不能把错簿当异常价格洗掉。</li><li>乱序、重复、缺口处理不同。</li><li>历史样本要打质量标志，否则回测吃进假深度。</li><li>恢复时长进入延迟预算的尾部。</li><li>出处：各交易所 ITCH / 订单簿协议对 sequence 与 snapshot 的公开文档；Hasbrouck 对完整微观结构记录的要求。</li></ul>',8))])}const D=B(p,[["render",A]]);export{q as __pageData,D as default};
